function Chart({series,xmin,xmax,ymin,ymax,xlabel,ylabel}:{series:any[],xmin:number,xmax:number,ymin:number,ymax:number,xlabel:string,ylabel:string}){const W=1000,H=410,L=80,R=28,T=30,B=60,X=(x:number)=>L+(x-xmin)/(xmax-xmin)*(W-L-R),Y=(y:number)=>H-B-(y-ymin)/(ymax-ymin)*(H-T-B);return <svg viewBox={`0 0 ${W} ${H}`} style={{width:'100%'}}>{[0,1,2,3,4].map(i=>{let v=ymin+(ymax-ymin)*i/4;return <g key={i}><line x1={L} x2={W-R} y1={Y(v)} y2={Y(v)} stroke="var(--border)"/><text x={L-10} y={Y(v)+5} fontSize="15" textAnchor="end" fill="var(--secondary)">{v.toFixed(ymax<2?2:0)}</text></g>})}{[0,1,2,3,4].map(i=>{let v=xmin+(xmax-xmin)*i/4;return <text key={i} x={X(v)} y={H-B+27} fontSize="15" textAnchor="middle" fill="var(--secondary)">{v.toFixed(xmax<2?2:0)}</text>})}{series.map((s,i)=><path key={s.name} d={s.points.map((v:number[],j:number)=>(j?'L':'M')+X(v[0])+','+Y(v[1])).join(' ')} stroke={s.color} strokeWidth="3" fill="none" strokeDasharray={s.dashed?'8 5':undefined}/>)}<text x={W/2} y={H-8} textAnchor="middle" fill="var(--foreground)" fontSize="17">{xlabel}</text><text x="24" y={H/2} transform={`rotate(-90 24 ${H/2})`} textAnchor="middle" fill="var(--foreground)" fontSize="17">{ylabel}</text></svg>}
function fromHist(h:any,name:string,color:string){let n=h.counts.reduce((a:number,b:number)=>a+b,0);return {name,color,points:[[h.edges[0],0],...h.counts.flatMap((c:number,i:number)=>[[h.edges[i],c/n*100],[h.edges[i+1],c/n*100]]),[h.edges[h.edges.length-1],0]]}}
export default function PaperComparison(){const [mode,setMode]=useState('em'),[step,setStep]=useState(100);const r=data.old_soft.find(x=>x.step===step)!;return <main style={{maxWidth:1150,margin:'auto',padding:26,fontFamily:'Georgia,serif',color:'var(--foreground)'}}><h1>Reward selection comparison</h1><div style={{display:'flex',gap:12}}>{[['em','512题EM曲线'],['std','每题reward std'],['adv','(c) 全部轨迹优势'],['active_adv','(d) std>0题组优势']].map(([m,l])=><button key={m} aria-pressed={mode===m} onClick={()=>setMode(m)} style={{padding:10,color:'var(--foreground)',background:'var(--background)',border:'1px solid var(--border)'}}>{l}</button>)}</div>{mode==='em'?<><div style={{display:'flex',gap:20,flexWrap:'wrap',margin:'24px 0'}}>{data.series.map((s,i)=><span key={s.name} style={{color:colors[i]}}>{s.name}</span>)}</div><Chart series={data.series.map((s,i)=>({name:s.name,color:colors[i],dashed:i===1,points:s.points.map(p=>[p.iteration,p.em*100])}))} xmin={50} xmax={200} ymin={35} ymax={55} xlabel="Training iteration" ylabel="Fixed512 EM (%)"/></>:<><p>同一Soft Reward实验的原始同题5条轨迹，分别计算Hard/Soft Reward。std使用correction=1。</p><select value={step} onChange={e=>setStep(+e.target.value)} aria-label="选择iteration" style={{padding:10}}>{data.old_soft.map(r=><option key={r.step}>{r.step}</option>)}</select><p style={{color:colors[0]}}>Soft Reward（蓝实线） · Hard Reward（橙实线）</p>{mode==='std'?<><Chart series={[fromHist(r.R_std_hist,'Soft Reward',colors[0]),fromHist(r.C_std_hist,'Hard Reward','#B46F26')]} xmin={0} xmax={1.01} ymin={0} ymax={100} xlabel="Within-question sample std" ylabel="Question frequency (%)"/><p>平均组内std：Soft {r.R_std.mean.toFixed(6)}；Hard {r.C_std.mean.toFixed(6)}。</p></>:<Chart series={[fromHist(mode==='active_adv'?r.R_active_A_hist:r.R_A_hist,'Soft Reward',colors[0]),fromHist(mode==='active_adv'?r.C_active_A_hist:r.C_A_hist,'Hard Reward','#B46F26')]} xmin={-1.85} xmax={1.85} ymin={0} ymax={mode==='active_adv'?40:100} xlabel="A = (r − mean_q) / (std_q + 1e−6)" ylabel="Trajectory frequency (%)"/>}{mode==='adv'&&<p>(c)：512组共2560条轨迹；std=0的整组也保留，其优势为0。</p>}{mode==='active_adv'&&<p>(d)：Hard、Soft分别保留各自std&gt;0的题组，分别重新归一化。Hard {(1-r.C_zero_group_fraction)*512}组、{(1-r.C_zero_group_fraction)*2560}条；Soft {(1-r.R_zero_group_fraction)*512}组、{(1-r.R_zero_group_fraction)*2560}条。不是删除单条A=0；此图仍可能出现A=0。</p>}<p>Soft Reward来自冻结历史probe重建；不是线上逐行原始奖励。另两实验完整历史Soft Reward分布尚未补齐。</p></>}</main>}
